/**
 * KS-733 — /api/users/me/mfa/* verified the SAME TOTP secret as /api/auth/mfa/*
 * but carried no path-scoped limiter, so in production it fell through to the
 * global 300/min: 4,500 attempts per 15 minutes against a secret the twin
 * surface caps at 10.
 *
 * This reads the mount table rather than issuing requests, following the KS-689
 * precedent: the property that failed is "is a limiter attached to this prefix",
 * and no gateway test boots index.ts. A behavioural test here would mostly be
 * exercising express-rate-limit, not our wiring.
 *
 * WHAT MAKES THIS MORE THAN A GREP. Three cells, and the parity cell is the one
 * that carries the ticket:
 *   - the CONTROL proves the extractor can find a mount that exists;
 *   - the NEGATIVE CONTROL proves it can say NO, so "found" is information;
 *   - the PARITY cell asserts the two surfaces carry the SAME window and max,
 *     which is the actual defect. A mount with max: 5000 would satisfy "is a
 *     limiter attached" and leave the asymmetry exactly where it was.
 *
 * WHAT IT IS BLIND TO, stated because the KS-689 header states its own bound:
 * this asserts the mount exists in source, not that express applies it to a
 * given request path, and not that the two limiters keep separate stores. The
 * separate-store property is load-bearing (a shared store would make the two
 * surfaces consume ONE budget, so traffic on one could lock out the other) and
 * it is guaranteed here only by the two rateLimit({...}) calls being distinct
 * object literals — which this file checks structurally and does not drive.
 */

import { describe, it, expect } from 'vitest';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

const GATEWAY_SRC = readFileSync(join(__dirname, '..', 'index.ts'), 'utf8');

/**
 * Return the full `app.use('<path>', ...)` call for a prefix, bounded by
 * balancing the call's own parentheses — the KS-689 lesson: slicing to the next
 * delimiter runs past the end and swallows the following mount, which makes a
 * negative control read as a pass.
 *
 * Returns null when there is no such mount, so the caller can assert absence.
 */
function mountCall(path: string): string | null {
  const needle = `app.use('${path}'`;
  const at = GATEWAY_SRC.indexOf(needle);
  if (at === -1) return null;
  const open = GATEWAY_SRC.indexOf('(', at);
  let depth = 0;
  for (let i = open; i < GATEWAY_SRC.length; i++) {
    const ch = GATEWAY_SRC[i];
    if (ch === '(') depth++;
    else if (ch === ')') {
      depth--;
      if (depth === 0) return GATEWAY_SRC.slice(at, i + 1);
    }
  }
  throw new Error(`unbalanced mount: app.use('${path}'`);
}

/** windowMs / max as written, so a drift between the two surfaces is visible. */
function limiterShape(call: string): { windowMs: string; max: string } {
  const windowMs = /windowMs:\s*([^,\n]+)/.exec(call)?.[1]?.trim() ?? '';
  const max = /max:\s*([^,\n]+)/.exec(call)?.[1]?.trim() ?? '';
  return { windowMs, max };
}

describe('KS-733 — the users MFA surface is rate-limited, at parity with the auth surface', () => {
  it('CONTROL — the extractor finds the existing /api/auth/mfa limiter', () => {
    // If this stops holding, every cell below is asserting nothing.
    const call = mountCall('/api/auth/mfa');
    expect(call, 'the /api/auth/mfa limiter mount was not found at all').not.toBeNull();
    expect(call).toContain('rateLimit(');
    const shape = limiterShape(call as string);
    expect(shape.windowMs).not.toBe('');
    expect(shape.max).not.toBe('');
  });

  it('NEGATIVE CONTROL — the extractor returns null for a prefix that carries no limiter mount', () => {
    // Without this, a matcher that reported "found" for anything would pass the
    // cell below, and "a limiter is mounted" would carry no information.
    expect(mountCall('/api/definitely-not-a-mounted-prefix-ks733')).toBeNull();
  });

  it('/api/users/me/mfa carries a path-scoped rate limiter', () => {
    const call = mountCall('/api/users/me/mfa');
    expect(call, 'no app.use rate-limit mount for /api/users/me/mfa').not.toBeNull();
    expect(call).toContain('rateLimit(');
  });

  it('PARITY — the users MFA limiter has the SAME window and max as the auth one', () => {
    // The defect was an ASYMMETRY, not an absence of any limit: production fell
    // through to the global 300/min. A mount with a laxer max would satisfy the
    // cell above and leave the 450x gap open.
    const authShape = limiterShape(mountCall('/api/auth/mfa') as string);
    const usersShape = limiterShape(mountCall('/api/users/me/mfa') as string);
    expect(usersShape.windowMs).toBe(authShape.windowMs);
    expect(usersShape.max).toBe(authShape.max);
  });
});
